import React from 'react';
import type { ExternalSyncOrchestration } from '../../../services/jobs/dataSyncModels';
import { JobDetailCollapsibleSection, JobDetailMetaGrid, formatJobDate } from './JobDetailMetaGrid';
import { formatDurationMs } from '../externalSyncRunDisplay';
import styles from '../JobInternalPage.module.css';

export type ExternalSyncRunOrchestrationSectionProps = {
  orchestration: ExternalSyncOrchestration;
  defaultOpen?: boolean;
};

const resolveEffectiveCap = (orchestration: ExternalSyncOrchestration): number =>
  orchestration.totalDetailParallelJobs ??
  orchestration.searchLaneCount * orchestration.detailParallelJobs;

export const ExternalSyncRunOrchestrationSection: React.FC<ExternalSyncRunOrchestrationSectionProps> = ({
  orchestration,
  defaultOpen = true,
}) => {
  const isRepost = orchestration.isLedgerRepost === true;
  const phaseRows = orchestration.phaseTimings.filter(
    (p) => p.completedCount > 0 || p.activeCount > 0 || p.failedCount > 0,
  );
  const totalDetailCap = resolveEffectiveCap(orchestration);
  const laneStats = orchestration.laneStats ?? [];
  const liveTotal = orchestration.liveTotalDetailParallelJobs;
  const liveLanes = orchestration.liveSearchLaneCount;
  const liveDetail = orchestration.liveDetailParallelJobs;
  const configAligned = orchestration.repostConfigAligned;

  const repostMetaItems = isRepost
    ? [
        {
          label: 'Config run vs DB',
          value:
            configAligned === true
              ? 'Khớp — post song song đúng config'
              : configAligned === false
                ? `Lệch — run ${orchestration.detailParallelJobs}, DB ${orchestration.liveParallelBatchJobs ?? '?'}`
                : '—',
          fullWidth: true,
        },
        {
          label: 'Post song song (leader cap)',
          value: `${orchestration.detailSlotsInUse} / ${totalDetailCap}`,
        },
        {
          label: 'Post import đang chạy (queue)',
          value:
            orchestration.postEventsInFlight != null
              ? orchestration.postEventsInFlight.toLocaleString('vi-VN')
              : '—',
        },
        {
          label: 'Checkpoint Processing',
          value:
            orchestration.checkpointsProcessingCap != null
              ? `${(orchestration.batchSlotsInUse ?? orchestration.detailSlotsInUse).toLocaleString('vi-VN')} / ${orchestration.checkpointsProcessingCap.toLocaleString('vi-VN')}`
              : '—',
        },
      ]
    : [];

  return (
    <JobDetailCollapsibleSection
      title={isRepost ? 'Leader re-post (PostImport 1:1)' : 'Leader & job song song'}
      defaultOpen={defaultOpen}
    >
      <JobDetailMetaGrid
        items={[
          {
            label: 'Leader (worker dispatch)',
            value: orchestration.leaderWorkerId ?? '—',
            mono: Boolean(orchestration.leaderWorkerId),
            fullWidth: true,
          },
          {
            label: 'Lần dispatch gần nhất',
            value: orchestration.lastLeaderDispatchAtUtc
              ? formatJobDate(orchestration.lastLeaderDispatchAtUtc)
              : '—',
          },
          {
            label: 'Chế độ',
            value: [
              orchestration.dispatchMode === 'leaderPool' ? 'Leader pool' : orchestration.dispatchMode,
              isRepost
                ? 'PostImport trực tiếp (1 CT / slot)'
                : orchestration.searchMode === 'sequential'
                  ? 'Search tuần tự'
                  : orchestration.searchMode === 'parallelLanes'
                    ? `Search ${orchestration.searchLaneCount} lane song song (run này)`
                    : orchestration.searchMode,
              orchestration.phase ? `Phase: ${orchestration.phase}` : null,
            ]
              .filter(Boolean)
              .join(' · ') || '—',
          },
          ...repostMetaItems,
          {
            label: isRepost ? 'Cap post song song (run)' : 'Leader run này',
            value: isRepost ? totalDetailCap : orchestration.searchLaneCount,
          },
          {
            label: isRepost ? 'Detail parallel (run)' : 'Job detail / leader',
            value: orchestration.detailParallelJobs,
          },
          {
            label: isRepost ? 'Slot post trống' : 'Cap detail song song (run)',
            value: isRepost
              ? orchestration.detailSlotsAvailable
              : `${totalDetailCap} (${orchestration.searchLaneCount}×${orchestration.detailParallelJobs})`,
          },
          {
            label: isRepost ? 'Post đang giữ slot' : 'Detail đang chạy',
            value: `${orchestration.detailSlotsInUse} / ${totalDetailCap}`,
          },
          {
            label: 'Pool chờ dispatch',
            value: orchestration.detailPoolPending.toLocaleString('vi-VN'),
          },
          {
            label: 'Thời gian run',
            value: formatDurationMs(orchestration.runDurationMs),
          },
        ]}
      />

      {isRepost && configAligned === false ? (
        <p className={styles.detailSummaryHeroHint} style={{ marginTop: 12 }}>
          Config DB hiện tại: <strong>{orchestration.liveParallelBatchJobs} post song song</strong>.
          Run này giữ snapshot lúc start: <strong>{orchestration.detailParallelJobs}</strong>.
          {' '}
          Muốn áp dụng config mới → dừng run và chạy lại Re-Post.
        </p>
      ) : null}

      {!isRepost && liveTotal != null && liveLanes != null && liveDetail != null ? (
        <p className={styles.detailSummaryHeroHint} style={{ marginTop: 12 }}>
          Config DB hiện tại (sync mới): <strong>{liveLanes}×{liveDetail} = {liveTotal}</strong> job song song.
          Run này giữ <strong>{orchestration.searchLaneCount} leader</strong> đã enqueue lúc start
          {orchestration.snapshotDetailParallelJobs != null
            ? ` · detail/leader lúc start ${orchestration.snapshotDetailParallelJobs}`
            : ''}
          .
          {' '}
          <strong>
            Muốn {liveLanes}×{liveDetail} → Dừng run + Resync
          </strong>{' '}
          để tạo run mới; run đang chạy không đổi số leader.
        </p>
      ) : null}

      {!isRepost ? (
        <p className={styles.detailSummaryHeroHint} style={{ marginTop: liveTotal != null ? 8 : 12 }}>
          Cap và dispatch detail đọc <strong>snapshot run</strong> ({orchestration.searchLaneCount}×{orchestration.detailParallelJobs} đã stamp lúc start).
          Lưu config DB mới không đổi cap run đang chạy — <strong>Dừng + Resync</strong> để áp dụng N×M mới.
        </p>
      ) : (
        <p className={styles.detailSummaryHeroHint} style={{ marginTop: 12 }}>
          Leader cap <strong>{totalDetailCap}</strong> · batch prepare{' '}
          <strong>{orchestration.itemsPerBatch ?? totalDetailCap}</strong> CT/event (
          <code>LedgerRepost.BatchRequested</code>, Task.WhenAll) · GL: 1{' '}
          <code>PostImport</code>/CT. Throughput GL phụ thuộc{' '}
          <strong>LowWorkerInstanceCount</strong> — nên ≥ cap post.
        </p>
      )}

      {!isRepost && laneStats.length > 0 ? (
        <div className={styles.detailTableWrap} style={{ marginTop: 12 }}>
          <table className={styles.detailTable} data-testid="external-sync-lane-stats">
            <thead>
              <tr>
                <th align="left">Lane</th>
                <th align="right">Pending</th>
                <th align="right">Processing</th>
                <th align="right">Cap</th>
                <th align="right">Slot trống</th>
              </tr>
            </thead>
            <tbody>
              {laneStats.map((lane) => (
                <tr key={lane.laneIndex}>
                  <td>L{lane.laneIndex}</td>
                  <td align="right">{lane.pending.toLocaleString('vi-VN')}</td>
                  <td align="right">{lane.processing.toLocaleString('vi-VN')}</td>
                  <td align="right">{lane.detailCap}</td>
                  <td align="right">{lane.slotsAvailable}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : null}

      <div className={styles.detailTableWrap} style={{ marginTop: 12 }}>
        <table className={styles.detailTable}>
          <thead>
            <tr>
              <th align="left">Phase</th>
              <th align="right">Hoàn tất</th>
              <th align="right">Đang chạy</th>
              <th align="right">Lỗi</th>
              <th align="right">Thời gian phase</th>
              <th align="right">TB / job</th>
              <th align="right">Max / job</th>
            </tr>
          </thead>
          <tbody>
            {(phaseRows.length > 0 ? phaseRows : orchestration.phaseTimings).map((p) => (
              <tr key={p.phaseKey}>
                <td>
                  <div style={{ fontWeight: 600 }}>{p.phaseLabel}</div>
                  <div className={styles.gridSub}>{p.eventType}</div>
                </td>
                <td align="right">{p.completedCount.toLocaleString('vi-VN')}</td>
                <td align="right">{p.activeCount > 0 ? p.activeCount.toLocaleString('vi-VN') : '—'}</td>
                <td align="right" style={{ color: p.failedCount > 0 ? '#b91c1c' : undefined }}>
                  {p.failedCount > 0 ? p.failedCount.toLocaleString('vi-VN') : '—'}
                </td>
                <td align="right">{formatDurationMs(p.totalDurationMs)}</td>
                <td align="right">{formatDurationMs(p.avgDurationMs)}</td>
                <td align="right">{formatDurationMs(p.maxDurationMs)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </JobDetailCollapsibleSection>
  );
};

export default ExternalSyncRunOrchestrationSection;
