import React, { useEffect } from 'react';
import { Navigate } from 'react-router-dom';
import { navigateToUrl } from 'single-spa';
import { isStandalone } from '../../dev/isStandalone';

/**
 * Embedded shell: login lives outside this MFE — use single-spa navigateToUrl.
 * Standalone: MemoryRouter Navigate to /login.
 */
export const AuthLoginRedirect: React.FC = () => {
  useEffect(() => {
    if (!isStandalone) {
      navigateToUrl('/login');
    }
  }, []);

  if (isStandalone) {
    return <Navigate to="/login" replace />;
  }

  return null;
};
