import { useEffect, useMemo, useState } from 'react';
import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import { voucherCodeFormatEndpoint } from '../../services/system/voucherCodeFormatEndpoint';

export type VoucherCodePrefixRow = {
  idCodePrefix: string;
  name: string;
};

function createVoucherCodePrefixSearchConfig(
  items: VoucherCodePrefixRow[],
): SearchInputConfig<VoucherCodePrefixRow> {
  return {
    api: {
      getItemKey: (item) => item.idCodePrefix,
      search: async ({ search, page, pageSize }) => {
        const term = (search ?? '').trim().toLowerCase();
        const filtered = term
          ? items.filter((item) => {
              const hay = `${item.idCodePrefix} ${item.name}`;
              return hay.toLowerCase().includes(term);
            })
          : items;
        const size = pageSize ?? 20;
        const totalPages = Math.max(1, Math.ceil(filtered.length / size));
        const start = (page - 1) * size;
        return {
          items: filtered.slice(start, start + size),
          page,
          totalPages,
        };
      },
      getDetail: async (idCodePrefix) => {
        const hit = items.find((i) => i.idCodePrefix === idCodePrefix);
        if (!hit) throw new Error('Không tìm thấy mã chứng từ');
        return hit;
      },
    },
    display: {
      getPrimaryDisplay: (item) => item.idCodePrefix,
      getSecondaryDisplay: (item) => item.name,
      getSingleDisplay: (item) => `${item.idCodePrefix} — ${item.name}`,
    },
    columns: [
      {
        key: 'prefix',
        variant: 'badge',
        width: '4.5rem',
        render: (item) => item.idCodePrefix,
      },
      {
        key: 'name',
        variant: 'primary',
        width: 'minmax(0, 1fr)',
        render: (item) => item.name,
      },
    ],
    header: {
      columns: [
        { key: 'prefix', label: 'Mã CT' },
        { key: 'name', label: 'Tên' },
      ],
    },
    dropdownPortal: true,
    dropdownMatch: 'row',
    texts: {
      empty: 'Không tìm thấy mã chứng từ',
      loading: 'Đang tải danh mục…',
    },
  };
}

export function useMissingLedgerRepostVoucherSearchConfig(): {
  config: SearchInputConfig<VoucherCodePrefixRow> | null;
  loading: boolean;
} {
  const [items, setItems] = useState<VoucherCodePrefixRow[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    const t = setTimeout(() => {
      voucherCodeFormatEndpoint
        .getList()
        .then((rows) => {
          if (cancelled) return;
          setItems(
            rows
              .filter((r) => r.isActive && r.prefix)
              .sort((a, b) => a.prefix.localeCompare(b.prefix))
              .map((r) => ({
                idCodePrefix: r.prefix,
                name: r.description,
              })),
          );
        })
        .catch(() => {
          if (!cancelled) setItems([]);
        })
        .finally(() => {
          if (!cancelled) setLoading(false);
        });
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, []);

  const config = useMemo(
    () => (items.length > 0 ? createVoucherCodePrefixSearchConfig(items) : null),
    [items],
  );

  return { config, loading };
}
